script !{
from io.github.himath2002.maze.api import GameScript, GameAPI
from javax.swing import JOptionPane

class PrizeCounter(object):
    def __init__(self):
        self.api = None
        self.obstacle_count = 0
        self.item_count = 0
        self.obstacle_positions = set()
        self.awarded = False

    def initialize(self, api):
        self.api = api
        self.api.setHasPrize(True)
        self.api.setPrizeProgress(0)

    def onPlayerMoved(self):
        if self.api.traversedObstacle():
            row = self.api.getPlayerRowIdx()
            col = self.api.getPlayerColIdx()
            pos = (row, col)
            if pos not in self.obstacle_positions:
                self.obstacle_positions.add(pos)
                self.obstacle_count += 1
                self.update_progress()

    def onItemAcquired(self, item):
        if item == "Golden Prize Key":
            return
        self.item_count += 1
        self.update_progress()

    def update_progress(self):
        total = self.obstacle_count + self.item_count
        shown = total if total <= 5 else 5
        self.api.setPrizeProgress(shown)

        if not self.awarded and total >= 5:
            self.awarded = True
            self.api.addItem("Golden Prize Key")
            JOptionPane.showMessageDialog(
                None,
                "Golden Prize Key added. Every obstacle can now be crossed.",
                "Prize",
                JOptionPane.INFORMATION_MESSAGE
            )

script = PrizeCounter()
}
